pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 n) public {
        // keep parameters in admissible, wide domain
        ts = bound(ts, 1, 1e15);
        n = bound(n, 1, 1e6);
        vm.assume(ts > n); // timestamp differs from block number (normal chain state)

        vm.warp(ts);
        vm.roll(n);
        vm.deal(address(this), 20 ether);

        // first call in this block succeeds
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call must succeed");

        // RULE: a second call in the SAME block must revert (one payout-block timestamp per block)
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "second call in same block must revert");
    }
}

