pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint32 t0, uint32 delta, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        uint256 start = 1000;
        vm.warp(start + (t0 % 1000));
        vm.roll(20); // not a multiple of 15: first call does not pay out

        vm.deal(actor, 20 ether);

        // first call: accepted by both P and M
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // second call: SAME block (same timestamp), possibly advanced in-block
        // admissible: still same block.timestamp
        vm.roll(21); // different block number, timestamp unchanged

        bool ok;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a call whose block.timestamp is NOT strictly greater
        // than the recorded pastBlockTime must revert.
        assertTrue(!ok, "second same-timestamp call must revert");
    }
}

