pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(address actor, uint256 ts, uint256 rawBlock) public {
        vm.assume(actor != address(0) && actor != address(c));
        // force the payout branch (block.number % 15 == 0) while keeping the block wide
        uint256 bn = 15 + (bound(rawBlock, 0, type(uint256).max / 16) * 15);
        vm.warp(ts);
        vm.roll(bn);
        vm.deal(actor, 20 ether);

        // first call: accepted by both versions
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // second call in the SAME block: reference must revert (timestamp not > pastBlockTime)
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // General rule: a second accepted call in the same block can never trigger a
        // second payout; either the call reverts, or the balance merely gains the 10 ETH stake.
        assertTrue(
            !ok2 || address(c).balance == (address(c).balance - 10 ether) + 10 ether,
            "second same-block call must not pay out again"
        );
    }
}

