    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(address actor, uint256 t, uint256 n) public {
        vm.assume(t > 0);                 // ensure the first call's require passes (0 is not > 0)
        vm.assume(n % 15 == 0);           // make the payout branch active (block.number % 15 == 0)
        vm.assume(n > 0);
        vm.assume(actor != address(0));

        vm.warp(t);
        vm.roll(n);

        // First call in this block: accepted by both C and M (timestamp t > initial pastBlockTime 0).
        vm.deal(actor, 20 ether);
        vm.prank(actor);
        bool ok1;
        try c.fallback{value: 10 ether}() { ok1 = true; } catch { ok1 = false; }

        // Second call in the SAME block (same timestamp): must be rejected by the reference.
        vm.prank(actor);
        bool ok2;
        try c.fallback{value: 10 ether}() { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok1 && !ok2);
    }
