pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockSeed, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        // drive execution to a block number divisible by 15 (a "winning" block)
        vm.roll(blockSeed * 15);
        // ensure timestamp strictly exceeds pastBlockTime (initially 0)
        vm.warp(1);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // The reference contract transferred its whole balance to the caller
        // on a winning block; the buggy one transfers 0 and keeps the funds.
        assertTrue(address(c).balance == 0);
    }
}

