pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 timestamp, uint256 blockNum, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 ts = timestamp;
        if (ts <= block.timestamp) ts = block.timestamp + 1;
        uint256 bn = bound(blockNum, 1, type(uint48).max);
        uint256 amount = 10 ether;
        vm.roll(bn);
        vm.warp(ts);
        vm.deal(address(this), amount);
        vm.deal(actor, 1 wei); // ensure actor exists as a funded recipient
        uint256 callerBefore = address(this).balance;
        uint256 cBalanceBefore = address(c).balance;
        bool ok;
        vm.roll(bn);
        vm.warp(ts);
        vm.prank(address(this));
        (ok,) = address(c).call{value: amount}("");
        assertTrue(ok);
        uint256 expectedGain = (bn % 15 == 0) ? cBalanceBefore : 0;
        assertTrue(address(this).balance == callerBefore + expectedGain);
        vm.deal(actor, 1 wei); // keep actor referenced (no-op observation)
    }
}

