pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint constant AMT = 10 ether;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        ts = bound(ts, 1, type(uint48).max);

        vm.warp(ts);
        vm.deal(actor, 2 * AMT);

        // first call at time ts
        vm.prank(actor);
        c.fallback{value: AMT}();

        // second call at the SAME timestamp
        vm.prank(actor);
        bool secondOk;
        try c.fallback{value: AMT}() { secondOk = true; } catch { secondOk = false; }

        // General rule: two successful calls must be at strictly increasing timestamps,
        // so a second call at the same timestamp must revert.
        assertTrue(!secondOk);
    }
}

