pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, uint256 ts, address actor) public {
        // choose a block number NOT congruent to 0 mod 15 (rule domain), keep domain wide
        blockNum = bound(blockNum, 0, type(uint64).max);
        vm.assume(blockNum % 15 != 0);
        ts = bound(ts, 2, type(uint64).max / 2);
        vm.deal(actor, 10 ether);

        // first call to initialize pastBlockTime (harmless: balance may change)
        vm.roll(blockNum);
        vm.warp(ts);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // second call at a strictly later timestamp, same block mod 15 domain
        uint256 balBefore = address(c).balance;
        vm.warp(ts + 1);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // GENERAL RULE: at a block number not divisible by 15, no payout happens,
        // so the contract balance only grows by the 10 ether sent in.
        // The mutant pays out when blockNum % 7 == 0 (e.g. 14, 28, 49...), breaking this.
        assertTrue(address(c).balance == balBefore + 10 ether);
    }
}

