contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, uint256 ts) public {
        blockNum = bound(blockNum, 1, 1_000_000);
        ts = bound(ts, 1, 1_000_000_000);
        vm.roll(blockNum);
        vm.warp(ts);

        uint256 pre = address(c).balance;
        vm.deal(address(this), 10 ether);

        // drive the payable fallback via low-level call (cannot call it by name)
        (bool ok, ) = address(c).call{value: 10 ether}("");

        uint256 bal = address(c).balance;
        assertTrue(
            ok && (blockNum % 15 != 0 ? bal == pre + 10 ether : bal == 0),
            "payout must occur exactly when block.number % 15 == 0"
        );
    }
}

