pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(address actor, uint64 ts, uint256 bn) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        bn = bound(bn, 0, type(uint256).max / 15 * 15);
        bn = bn - (bn % 15); // force winning block number % 15 == 0
        ts = uint64(bound(uint256(ts), 1, type(uint64).max));

        vm.deal(actor, 10 ether);
        vm.roll(bn);
        vm.warp(ts);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}(hex"");
        assertTrue(ok);

        // General rule: on a winning block the full balance (initial 10 ether
        // endowment + the 10 ether deposit = 20 ether) is paid out, so the
        // contract must be left with zero balance. The mutant pays only
        // msg.value (10 ether) and leaves 10 ether behind.
        assertTrue(address(c).balance == 0);
    }
}
